const ids = ["1:24","1:27","1:32","1:42","1:269","1:270","1:271","1:212","1:218","1:220","1:230","1:239","1:240","1:232"];
const out = [];
function dump(n, depth){
  const o = {id:n.id, name:n.name, type:n.type, w:Math.round(n.width), h:Math.round(n.height)};
  if(n.type==="TEXT"){o.chars=n.characters; o.fontName=n.fontName; o.fontSize=n.fontSize; o.fills=JSON.stringify(n.fills).slice(0,120);}
  if("cornerRadius" in n && n.cornerRadius!==undefined && n.cornerRadius!==0) o.r=n.cornerRadius;
  if(n.fills && n.type!=="TEXT" && Array.isArray(n.fills) && n.fills.length) o.fill=n.fills[0].type==="SOLID"?("#"+n.fills[0].color && Object.values(n.fills[0].color).map(v=>Math.round(v*255).toString(16).padStart(2,"0")).join("")):n.fills[0].type;
  if("strokes" in n && n.strokes && n.strokes.length) o.stroke=true;
  out.push("  ".repeat(depth)+JSON.stringify(o));
  if("children" in n && depth<3) for(const c of n.children) dump(c, depth+1);
}
for(const id of ids){const n=await figma.getNodeByIdAsync(id); if(n) dump(n,0); else out.push(id+" MISSING");}
// workspace page
const ws = await figma.getNodeByIdAsync("3:2");
out.push("WORKSPACE children: "+ws.children.map(c=>c.id+" "+c.name+" "+c.type).join(" | "));
// fonts used
const btn = await figma.getNodeByIdAsync("1:24");
return out.join("\n");

