const page = await figma.getNodeByIdAsync("3:2");
const screens = page.children.filter(n=>/^\d\d_/.test(n.name));
const out=[];
let total=0;
for(const f of screens){
 const nodes=f.findAll(n=>n.reactions&&n.reactions.length>0);
 const links=nodes.map(n=>n.name+"->"+(n.reactions[0].actions[0].destinationId||"?"));
 total+=nodes.length;
 out.push(f.name+" ["+nodes.length+"]: "+links.join(", "));
}
out.push("TOTAL="+total);
return out.join("\n");
